import { readFileSync, writeFileSync } from 'node:fs';
import { resolve } from 'node:path';

import Ajv2020 from 'ajv/dist/2020.js';
import standaloneCode from 'ajv/dist/standalone/index.js';

const generated = resolve('src/generated');
const schema = JSON.parse(readFileSync(resolve(generated, 'server-message.schema.json'), 'utf8'));
const ajv = new Ajv2020({
  allErrors: true,
  strict: false,
  validateFormats: false,
  code: { source: true, esm: true },
});
const validate = ajv.compile(schema);
const source = [
  '// @generated by `pnpm generate:validators`.',
  '// Do not edit manually.',
  '',
  standaloneCode(ajv, validate),
].join('\n');

writeFileSync(resolve(generated, 'server-message-validator.js'), source);
writeFileSync(
  resolve(generated, 'server-message-validator.d.ts'),
  [
    '// @generated by `pnpm generate:validators`.',
    '// Do not edit manually.',
    '',
    "import type { ValidateFunction } from 'ajv';",
    '',
    'declare const validate: ValidateFunction;',
    'export default validate;',
    '',
  ].join('\n'),
);

console.log('generated CSP-safe standalone protocol validator');
